import Foundation

// Holes 25–100: six worlds of 13, 13, 13, 13, 13 and 11 holes (see
// `GolfHoles.worlds`). Made by a seeded generator from track shapes, rails
// and each world's pieces, then checked by a solver that tries shots from the
// tee and from where they stop: every hole can be sunk in its par.
//
// Kept as JSON, one hole per line, and read on first use: as a Swift array
// literal this much data made optimised builds crawl. Points are [x, y],
// rectangles [[x, y], [width, height]], in the 320 × 460 course field.

extension GolfHoles {
    static let generated: [GolfHole] = {
        do {
            return try JSONDecoder().decode([GolfHole].self, from: Data(json.utf8))
        } catch {
            assertionFailure("Mini golf holes failed to load: \(error)")
            return []
        }
    }()

